import { useState, useEffect } from 'react';

export function AutoSync() {
  const [settings, setSettings] = useState({ theme: 'dark', autoSave: true, lastSynced: null });

  useEffect(() => {
    // ✅ Only run sync interval or trigger update conditionally without settings in dependency array
    const interval = setInterval(() => {
      setSettings(prev => ({ ...prev, lastSynced: Date.now() }));
    }, 10000);

    return () => clearInterval(interval);
  }, []); // Empty deps array prevents infinite state re-triggering

  return <div>Last synced: {settings.lastSynced ?? 'Never'}</div>;
}

